    core = v
    plus = core.find('+')
    if plus != -1:
        core = core[:plus]

    pre = None
    dash = core.find('-')
    if dash != -1:
        pre = core[dash + 1:]
        core = core[:dash]

    major, minor, patch = core.split('.')
    return int(major), int(minor), int(patch), pre


def _ident_key(ident):
    if ident and all('0' <= c <= '9' for c in ident):
        return (0, int(ident), '')
    return (1, 0, ident)


def _pre_key(pre):
    # No pre-release outranks any pre-release for the same core version.
    if pre is None:
        return (1,)
