def _sort_key(v):
    major, minor, patch, pre = _parse(v)
    return (major, minor, patch, _pre_key(pre))


def sort_versions(vs):
    """Sort semantic version strings by SemVer 2.0.0 precedence, lowest first.

    Build metadata is ignored for ordering.  Ties preserve input order.
    """
    return sorted(vs, key=_sort_key)
